// Service worker: makes the app install and work fully offline.
// The list of files and the version below are generated by tools/build.py.
// Whenever any app file changes, the version changes, so every device picks up
// the whole new set of files together the next time it opens the app.

// BUILD-START (generated, do not edit by hand)
const VERSION = "8980821c1bbb";
const FILES = [
  "./",
  "config.js",
  "fonts/BricolageGrotesque-latin-3b58e8.woff2",
  "fonts/BricolageGrotesque-latin-ext-10d6a5.woff2",
  "fonts/Figtree-latin-ext-7471c0.woff2",
  "fonts/Figtree-latin-f96cbb.woff2",
  "fonts/IBMPlexMono-latin-a80b2c.woff2",
  "fonts/IBMPlexMono-latin-bc87d8.woff2",
  "fonts/IBMPlexMono-latin-ext-25040c.woff2",
  "fonts/IBMPlexMono-latin-ext-7963a1.woff2",
  "fonts/fonts.css",
  "icons/apple-touch-icon.png",
  "icons/favicon.svg",
  "icons/icon-192.png",
  "icons/icon-512.png",
  "icons/maskable-512.png",
  "js/app.js",
  "js/auth.js",
  "js/crypto.js",
  "js/drive.js",
  "js/merge.js",
  "js/statement.js",
  "js/store.js",
  "js/sync.js",
  "manifest.webmanifest",
  "vendor/pdfjs/pdf.min.mjs",
  "vendor/pdfjs/pdf.worker.min.mjs",
  "vendor/pdfjs/standard_fonts/FoxitDingbats.pfb",
  "vendor/pdfjs/standard_fonts/FoxitFixed.pfb",
  "vendor/pdfjs/standard_fonts/FoxitFixedBold.pfb",
  "vendor/pdfjs/standard_fonts/FoxitFixedBoldItalic.pfb",
  "vendor/pdfjs/standard_fonts/FoxitFixedItalic.pfb",
  "vendor/pdfjs/standard_fonts/FoxitSerif.pfb",
  "vendor/pdfjs/standard_fonts/FoxitSerifBold.pfb",
  "vendor/pdfjs/standard_fonts/FoxitSerifBoldItalic.pfb",
  "vendor/pdfjs/standard_fonts/FoxitSerifItalic.pfb",
  "vendor/pdfjs/standard_fonts/FoxitSymbol.pfb",
  "vendor/pdfjs/standard_fonts/LiberationSans-Bold.ttf",
  "vendor/pdfjs/standard_fonts/LiberationSans-BoldItalic.ttf",
  "vendor/pdfjs/standard_fonts/LiberationSans-Italic.ttf",
  "vendor/pdfjs/standard_fonts/LiberationSans-Regular.ttf"
];
// BUILD-END

const CACHE = "ccl-" + VERSION;
// Fetched fresh when online so that editing it takes effect without a rebuild
const NETWORK_FIRST = ["config.js"];

self.addEventListener("install", event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await cache.addAll(FILES.map(f => new Request(f, { cache: "reload" })));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith("ccl-") && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", event => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // Google sign-in and Drive always go to the network
  const scope = new URL(self.registration.scope);
  const rel = url.pathname.startsWith(scope.pathname) ? url.pathname.slice(scope.pathname.length) : url.pathname;

  if (NETWORK_FIRST.includes(rel)) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      try {
        const fresh = await fetch(req, { cache: "no-cache" });
        if (fresh.ok) cache.put(req, fresh.clone());
        return fresh;
      } catch (_) {
        return (await cache.match(req)) || Response.error();
      }
    })());
    return;
  }

  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // The app page itself, whatever the exact URL (with ?query, index.html ...)
    if (req.mode === "navigate") {
      const hit = await cache.match("./", { ignoreSearch: true });
      if (hit) return hit;
    }
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch (_) {
      return Response.error();
    }
  })());
});
